```tsx
import { useState } from 'react';
import type { ChangeEvent, FormEvent } from 'react';
import { Screen, Card, Stack, TextField, Button, Alert } from '@nexti/ds';
import type { ScreenProps } from './types';

type Tone = 'info' | 'success' | 'warning' | 'error';

const OPTIONS = [
  { value: '1', label: 'Pagar una orden', target: 'SCR-PAGOORD' },
  // The spec does not state which screen "Consultar una orden" opens.
  // SCR-PAGORES is assumed; confirm at gate C2.
  { value: '2', label: 'Consultar una orden', target: 'SCR-PAGORES' },
];

function todayText(): string {
  const d = new Date();
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yy = String(d.getFullYear() % 100).padStart(2, '0');
  return `${dd}/${mm}/${yy}`;
}

export default function PagomenScreen({ navigate }: ScreenProps) {
  const [opcion, setOpcion] = useState('');
  const [error, setError] = useState('');
  const [mensaje, setMensaje] = useState('');
  const [tone, setTone] = useState<Tone>('info');

  const fecha = todayText();

  function fail(msg: string) {
    setError(msg);
    setMensaje(msg);
    setTone('error');
  }

  function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (opcion === '') {
      fail('Ingrese una opción (campo obligatorio).');
      return;
    }
    const found = OPTIONS.find((o) => o.value === opcion);
    if (!found) {
      fail('Opción inválida. Ingrese 1 o 2.');
      return;
    }
    setError('');
    setTone('success');
    setMensaje(`Opción ${found.value} seleccionada: ${found.label}.`);
    navigate(found.target);
  }

  function salir() {
    setError('');
    setTone('info');
    setMensaje('Ha salido del menú de pagos.');
  }

  function handleChange(e: ChangeEvent<HTMLInputElement>) {
    // Numeric field, maximum length 1
    const digit = e.target.value.replace(/\D/g, '').slice(0, 1);
    setOpcion(digit);
    if (error) setError('');
  }

  return (
    <Screen title="Banco ficticio - Pagos">
      <form onSubmit={handleSubmit} noValidate>
        <Stack>
          <div data-field="FECHA">
            <span>Fecha: </span>
            <span>{fecha}</span>
          </div>

          <Card title="Menú de pagos">
            <Stack>
              <ul aria-label="Opciones disponibles" style={{ margin: 0, paddingLeft: 20 }}>
                {OPTIONS.map((o) => (
                  <li key={o.value}>
                    {o.value}. {o.label}
                  </li>
                ))}
              </ul>

              <div data-field="OPCION">
                <TextField
                  label="OPCION"
                  required
                  numeric
                  maxLength={1}
                  error={error || undefined}
                  value={opcion}
                  onChange={handleChange}
                />
              </div>

              <div>
                <Button type="button" variant="ghost" data-action="PF3" onClick={salir}>
                  SALIR
                </Button>
                <Button type="submit" variant="primary" data-action="ENTER">
                  CONTINUAR
                </Button>
              </div>
            </Stack>
          </Card>

          <div data-field="MENSAJE" aria-live="polite">
            {mensaje ? (
              <Alert tone={tone}>
                <span>{mensaje.slice(0, 78)}</span>
              </Alert>
            ) : null}
          </div>
        </Stack>
      </form>
    </Screen>
  );
}
```

The compile error came from `TextField`'s `onChange`, which takes a change event rather than a string. `handleChange` now reads `e.target.value` from a `ChangeEvent<HTMLInputElement>`.

I made three other changes:
- **Imports:** I now use only the design-system components named in the spec (`Screen`, `Card`, `Stack`, `TextField`, `Button`, `Alert`), plus `ScreenProps` for the props type.
- **Submit:** ENTER is a real submit button inside a `<form>`.
- **Date:** `FECHA` shows today's date instead of the prototype's sample value.

Two behaviours come straight from the prototype and are unconfirmed:
- Option 2 navigates to `SCR-PAGORES`, which the prototype itself marks as an assumption to confirm at gate C2.
- PF3 has no target in the contract, so it only shows an exit message and does not navigate.

I haven't compiled this against the platform's design-system types, so the `type` and `data-action` props on `Button` are assumed to be accepted.
